templates.template:
.wrxtHata-floatingButton { position: fixed; right: 22px; bottom: 22px; z-index: @zIndex-4; }
.wrxtHata-footerButton { padding: @xf-paddingLarge 0; text-align: center; }
.wrxtHata-reportButton { font-weight: 700; font-size: @xf-fontSizeNormal; box-shadow: 0 4px 16px rgba(0,0,0,.22); border-radius: @xf-borderRadiusLarge; padding: 10px 16px; }
.wrxtHata-reportButton .fa { margin-right: 6px; }
.wrxtHata-diagnosticItem { padding: @xf-paddingMedium 0; border-bottom: 1px solid @xf-borderColorLight; }
.wrxtHata-diagnosticItem:last-child { border-bottom: 0; }
@media (max-width: @xf-responsiveMedium) { .wrxtHata-floatingButton { right: 12px; bottom: 12px; } .wrxtHata-reportButton { padding: 9px 13px; } }
.wrxtHata-url { overflow-wrap: anywhere; word-break: break-word; }

/* Warext Studios - ACP hata bildirim arayuzu */
.wrxtHata-techGrid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: @xf-paddingMedium;
}
.wrxtHata-techItem {
    min-width: 0;
    padding: @xf-paddingMedium;
    border: 1px solid @xf-borderColorLight;
    border-radius: 4px;
}
.wrxtHata-techLabel {
    margin-bottom: 4px;
    font-size: 12px;
    font-weight: 700;
    opacity: .72;
}
.wrxtHata-techValue {
    min-width: 0;
    line-height: 1.45;
    overflow-wrap: anywhere;
    word-break: normal;
}
.wrxtHata-techValue a,
.wrxtHata-url,
.wrxtHata-diagnosticText {
    overflow-wrap: anywhere;
    word-break: break-word;
}
.wrxtHata-codeWrap {
    min-width: 0;
    max-width: 100%;
    overflow: hidden;
}
.wrxtHata-code {
    box-sizing: border-box;
    width: 100%;
    max-width: 100%;
    max-height: 420px;
    margin: 0;
    overflow: auto;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    word-break: break-word;
}
.wrxtHata-tableScroll {
    width: 100%;
    max-width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}
.wrxtHata-tableScroll .dataList-table {
    width: 100%;
    min-width: 760px;
}
.wrxtHata-tableScroll th,
.wrxtHata-tableScroll td {
    vertical-align: top;
}
.wrxtHata-logAction { min-width: 190px; }
.wrxtHata-logValue { min-width: 150px; max-width: 320px; overflow-wrap: anywhere; word-break: break-word; }
.wrxtHata-logActor { width: 110px; white-space: nowrap; }
.wrxtHata-logDate { width: 170px; white-space: nowrap; }
.wrxtHata-diagnosticMeta { margin-top: 4px; overflow-wrap: anywhere; word-break: break-word; }
@media (max-width: @xf-responsiveMedium) {
    .wrxtHata-techGrid { grid-template-columns: 1fr; }
    .wrxtHata-techItem { padding: @xf-paddingSmall @xf-paddingMedium; }
}
